import React, { useRef, useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Users, Award, Clock, Heart, Sparkles, Star, Zap, ShieldCheck, TrendingUp, Target } from 'lucide-react';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const About = () => {
  const containerRef = useRef<HTMLElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const leftContentRef = useRef<HTMLDivElement>(null);
  const rightContentRef = useRef<HTMLDivElement>(null);
  const valuesRef = useRef<HTMLDivElement>(null);
  const bottomCtaRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    // Force refresh to handle dynamic content height changes
    ScrollTrigger.refresh();

    // 1. Header Animation
    gsap.fromTo(headerRef.current?.children || [],
      { y: 50, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        stagger: 0.2,
        duration: 1,
        ease: "power3.out",
        scrollTrigger: {
          trigger: headerRef.current,
          start: "top 80%",
          toggleActions: "play none none reverse"
        }
      }
    );

    // 2. Main Content (Left Text)
    if (leftContentRef.current) {
      gsap.fromTo(leftContentRef.current,
        { x: -50, opacity: 0 },
        {
          x: 0,
          opacity: 1,
          duration: 1,
          ease: "power3.out",
          scrollTrigger: {
            trigger: leftContentRef.current,
            start: "top 75%",
            toggleActions: "play none none reverse"
          }
        }
      );
    }

    // 3. Main Content (Right Stats) - Staggered
    gsap.fromTo(rightContentRef.current?.children || [],
      { x: 50, opacity: 0 },
      {
        x: 0,
        opacity: 1,
        stagger: 0.1,
        duration: 0.8,
        ease: "power3.out",
        scrollTrigger: {
          trigger: rightContentRef.current,
          start: "top 75%",
          toggleActions: "play none none reverse"
        }
      }
    );

    // 4. Values Cards Stagger
    gsap.fromTo(valuesRef.current?.children || [],
      { y: 60, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        stagger: 0.1,
        duration: 0.8,
        ease: "back.out(1.2)",
        scrollTrigger: {
          trigger: valuesRef.current,
          start: "top 80%",
          toggleActions: "play none none reverse"
        }
      }
    );

    // 5. Bottom CTA
    if (bottomCtaRef.current) {
      gsap.fromTo(bottomCtaRef.current,
        { scale: 0.9, opacity: 0 },
        {
          scale: 1,
          opacity: 1,
          duration: 0.8,
          ease: "elastic.out(1, 0.5)",
          scrollTrigger: {
            trigger: bottomCtaRef.current,
            start: "top 85%",
            toggleActions: "play none none reverse"
          }
        }
      );
    }

    // 6. Background Parallax
    gsap.to(".bg-blob", {
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top bottom",
        end: "bottom top",
        scrub: 1
      },
      y: 150,
      ease: "none"
    });

  }, { scope: containerRef });

  // Static styling configuration to preserve premium look
  const styleConfig = [
    { color: "from-blue-500 to-cyan-400", bgColor: "bg-blue-500/10" },
    { color: "from-purple-500 to-pink-400", bgColor: "bg-purple-500/10" },
    { color: "from-green-500 to-emerald-400", bgColor: "bg-green-500/10" },
    { color: "from-yellow-400 to-orange-400", bgColor: "bg-yellow-500/10" }
  ];

  const [stats, setStats] = useState([
    // Default initial state while loading
    { icon: <Users className="w-8 h-8" />, number: "...", label: "Global Clients", ...styleConfig[0] },
    { icon: <Award className="w-8 h-8" />, number: "...", label: "Projects Delivered", ...styleConfig[1] },
    { icon: <Clock className="w-8 h-8" />, number: "...", label: "Years of Excellence", ...styleConfig[2] },
    { icon: <Star className="w-8 h-8" />, number: "4.9/5", label: "Average Rating", ...styleConfig[3] }
  ]);

  const IconMap: Record<string, any> = { Users, Award, Clock, Heart };

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const { data, error } = await supabase
          .from('stats')
          .select('*')
          .order('sort_order', { ascending: true });

        if (data) {
          const mergedStats = data.map((stat, index) => ({
            icon: IconMap[stat.icon_name] ? React.createElement(IconMap[stat.icon_name], { className: "w-8 h-8" }) : <Users className="w-8 h-8" />,
            number: stat.value,
            label: stat.label,
            ...styleConfig[index % styleConfig.length] // Cycle through styles if more stats than configs
          }));
          setStats(mergedStats);
        }
      } catch (error) {
        console.error("Error loading stats:", error);
      }
    };
    fetchStats();
  }, []);

  const values = [
    {
      icon: <Sparkles className="w-12 h-12" />,
      title: "Pioneering Innovation",
      description: "Leveraging emerging technologies to create future-proof digital solutions that position your brand at the forefront of your industry.",
      gradient: "from-yellow-400 via-orange-500 to-red-500"
    },
    {
      icon: <Star className="w-12 h-12" />,
      title: "Uncompromising Excellence",
      description: "Delivering precision-engineered digital products where every detail is meticulously crafted to meet global standards of perfection.",
      gradient: "from-blue-400 via-purple-500 to-pink-500"
    },
    {
      icon: <Zap className="w-12 h-12" />,
      title: "Agile Efficiency",
      description: "Streamlined workflows and agile methodologies ensure rapid deployment without ever sacrificing the integrity or quality of your solution.",
      gradient: "from-green-400 via-blue-500 to-purple-500"
    },
    {
      icon: <ShieldCheck className="w-12 h-12" />,
      title: "Absolute Integrity",
      description: "Fostering long-term partnerships through complete clarity in pricing, processes, and communication. No hidden clauses, just honest collaboration.",
      gradient: "from-cyan-400 via-blue-500 to-indigo-500"
    },
    {
      icon: <Target className="w-12 h-12" />,
      title: "Strategic Impact",
      description: "Aligning our technical expertise with your business objectives to deliver measurable ROI and sustainable market growth.",
      gradient: "from-pink-400 via-rose-500 to-red-500"
    },
    {
      icon: <TrendingUp className="w-12 h-12" />,
      title: "Enduring Success",
      description: "Providing ongoing optimization and scalability support to ensure your digital presence evolves alongside your business ambitions.",
      gradient: "from-violet-400 via-purple-500 to-fuchsia-500"
    }
  ];

  return (
    <section id="about" ref={containerRef} className="py-32 bg-background relative overflow-hidden">
      {/* Animated Background Elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="bg-blob absolute top-10 left-10 w-72 h-72 bg-gradient-to-r from-blue-600/10 to-purple-600/10 rounded-full blur-3xl"></div>
        <div className="bg-blob absolute bottom-10 right-10 w-96 h-96 bg-gradient-to-r from-pink-600/10 to-purple-600/10 rounded-full blur-3xl"></div>
        <div className="bg-blob absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-gradient-to-r from-green-500/5 to-blue-500/5 rounded-full blur-3xl"></div>

        {/* Floating Sparkles */}
        <Sparkles className="absolute top-20 right-1/4 w-8 h-8 text-yellow-500/20 animate-sparkle" />
        <Star className="absolute bottom-32 left-1/3 w-6 h-6 text-pink-500/20 animate-bounce" />
        <Zap className="absolute top-1/3 right-1/3 w-10 h-10 text-purple-500/20 animate-pulse" />
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        {/* Header */}
        <div ref={headerRef} className="text-center mb-20">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-r from-purple-600 to-pink-600 rounded-full mb-8 shadow-lg shadow-purple-500/20 animate-pulse">
            <Heart className="w-10 h-10 text-white" />
          </div>
          <h2 className="text-6xl md:text-7xl font-bold mb-6 text-white">
            About{' '}
            <span className="bg-gradient-to-r from-blue-400 via-purple-400 to-pink-400 bg-clip-text text-transparent bg-300% animate-gradient-shift">
              Our Journey
            </span>
          </h2>
          <p className="text-2xl text-gray-200 max-w-4xl mx-auto leading-relaxed">
            We are more than a digital agency. We are the{' '}
            <span className="text-purple-400 font-bold">architects of your digital future</span>,
            turning ambitious visions into breathtaking realities.
          </p>
        </div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center mb-24">
          {/* Left Content */}
          <div ref={leftContentRef}>
            <div className="bg-white/5 backdrop-blur-lg rounded-3xl p-10 shadow-2xl border border-white/10 hover:border-white/20 transition-all duration-500 transform hover:-translate-y-2">
              <h3 className="text-4xl font-bold text-white mb-6">
                Redefining Digital{' '}
                <span className="bg-gradient-to-r from-orange-400 to-red-400 bg-clip-text text-transparent">
                  Excellence
                </span>
              </h3>
              <p className="text-lg text-gray-200 mb-6 leading-relaxed">
                YourWebPartner wasn't built to just "make websites." It was born from a frustration with mediocrity.
                We saw too many businesses settling for cookie-cutter templates that failed to capture their unique essence.
                We knew there had to be a better way—a way to blend <strong>stunning aesthetics</strong> with <strong>powerful functionality</strong>.
              </p>
              <p className="text-lg text-gray-200 mb-8 leading-relaxed">
                Today, we stand as a beacon for brands that refuse to blend in. Our team of visionary designers and
                master developers works in perfect sync to craft digital experiences that don't just look good—they feel right,
                perform flawlessly, and drive measurable growth. When you partner with us, you're not just getting a service provider;
                you're gaining a dedicated ally in your pursuit of greatness.
              </p>

              {/* Call to Action */}
              <a href="/#values" className="group relative px-8 py-4 bg-transparent border border-white/20 text-white font-bold rounded-full hover:shadow-2xl transition-all duration-500 transform hover:scale-105 overflow-hidden inline-block">
                <span className="relative z-10 flex items-center gap-2">
                  Read Our Full Story
                  <Sparkles className="w-5 h-5 group-hover:animate-spin" />
                </span>
                <div className="absolute inset-0 bg-gradient-to-r from-purple-600/20 via-pink-600/20 to-red-600/20 opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
              </a>
            </div>
          </div>

          {/* Right Content - Stats */}
          <div ref={rightContentRef} className="grid grid-cols-2 gap-6">
            {stats.map((stat, index) => (
              <div
                key={index}
                className={`${stat.bgColor} backdrop-blur-sm rounded-3xl p-8 text-center hover:shadow-2xl transition-all duration-500 transform hover:-translate-y-4 hover:rotate-2 group cursor-pointer border border-white/5 hover:border-white/20`}
              >
                <div className={`inline-flex items-center justify-center w-16 h-16 bg-gradient-to-r ${stat.color} text-white rounded-full mb-4 group-hover:scale-125 transition-transform duration-300 shadow-lg`}>
                  {stat.icon}
                </div>
                <div className={`text-4xl font-bold bg-gradient-to-r ${stat.color} bg-clip-text text-transparent mb-2 group-hover:scale-110 transition-transform duration-300`}>
                  {stat.number}
                </div>
                <div className="text-gray-400 font-semibold group-hover:text-white transition-colors duration-300">
                  {stat.label}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Values Section */}
        <div className="text-center mb-16">
          <h3 className="text-5xl font-bold text-white mb-4">
            Our{' '}
            <span className="bg-gradient-to-r from-green-400 to-blue-400 bg-clip-text text-transparent">
              Core Values
            </span>
          </h3>
          <p className="text-xl text-gray-400 max-w-3xl mx-auto">
            The guiding principles that drive our innovation and ensure your success.
          </p>
        </div>

        <div ref={valuesRef} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 relative z-10">
          {values.map((value, index) => (
            <div
              key={index}
              className="group relative bg-white/5 backdrop-blur-lg rounded-3xl p-8 text-center hover:shadow-2xl transition-all duration-700 transform hover:-translate-y-4 hover:rotate-1 border border-white/10 hover:border-white/20 overflow-hidden"
            >
              {/* Animated Background */}
              <div className={`absolute inset-0 bg-gradient-to-br ${value.gradient} opacity-0 group-hover:opacity-10 transition-opacity duration-700 rounded-3xl`}></div>

              {/* Icon */}
              <div className={`inline-flex items-center justify-center w-20 h-20 bg-gradient-to-r ${value.gradient} text-white rounded-full mb-6 group-hover:scale-125 group-hover:rotate-12 transition-all duration-500 shadow-xl relative z-10`}>
                {value.icon}
              </div>

              {/* Content */}
              <h4 className="text-2xl font-bold text-white mb-4 group-hover:text-transparent group-hover:bg-clip-text group-hover:bg-gradient-to-r group-hover:from-white group-hover:to-gray-200 transition-all duration-300 relative z-10">
                {value.title}
              </h4>
              <p className="text-gray-400 leading-relaxed group-hover:text-gray-300 transition-colors duration-300 relative z-10">
                {value.description}
              </p>

              {/* Hover Effect Particles */}
              <div className="absolute inset-0 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                {[...Array(3)].map((_, i) => (
                  <div
                    key={i}
                    className="absolute w-1 h-1 bg-white rounded-full animate-sparkle"
                    style={{
                      left: `${20 + Math.random() * 60}%`,
                      top: `${20 + Math.random() * 60}%`,
                      animationDelay: `${i * 0.3}s`
                    }}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>

        {/* Bottom CTA */}
        <div ref={bottomCtaRef} className="text-center mt-20">
          <div className="bg-gradient-to-r from-purple-900/50 via-pink-900/50 to-red-900/50 backdrop-blur-md border border-white/10 rounded-3xl p-12 text-white relative overflow-hidden">
            <div className="absolute inset-0 bg-white/5 opacity-10 animate-pulse"></div>
            <div className="relative z-10">
              <h4 className="text-4xl font-bold mb-4">Ready to Build Your Legacy?</h4>
              <p className="text-xl mb-8 text-gray-300">Don't settle for ordinary. Let's build something extraordinary.</p>
              <a href="/#contact" className="group relative px-12 py-6 bg-white text-purple-600 font-bold rounded-full hover:shadow-2xl transition-all duration-500 transform hover:scale-110 overflow-hidden inline-block cursor-pointer">
                <span className="relative z-10">Start Your Project</span>
                <div className="absolute inset-0 bg-purple-600 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                <span className="absolute inset-0 flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-20">
                  Contact Us Now
                </span>
              </a>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;

import React, { useEffect, useState } from 'react';
import { BarChart3, TrendingUp, Users, Eye, MousePointer, Clock, Activity } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';

const AdvancedAnalytics = () => {
  const [analytics, setAnalytics] = useState({
    visitors: 0,
    pageViews: 0,
    conversionRate: 0,
    avgTimeOnSite: '0:00',
    topPages: [] as any[],
    recentActivity: [] as string[]
  });


  // ...

  useEffect(() => {
    const fetchRealData = async () => {
      try {
        // 1. Get Total Page Views
        const { count: pageViewsCount } = await supabase
          .from('page_views')
          .select('*', { count: 'exact', head: true });

        // 2. Get Top Pages (Aggregation)
        // Since we can't easily do SQL GROUP BY via JS client without RPC, we'll fetch last 1000 views
        // and calculate client-side for this MVP.
        const { data: recentViews } = await supabase
          .from('page_views')
          .select('page_path, created_at')
          .order('created_at', { ascending: false })
          .limit(500);

        if (recentViews) {
          const pageCounts: Record<string, number> = {};
          recentViews.forEach(v => {
            const path = v.page_path === '/' ? 'Home' : v.page_path.replace('/', '');
            pageCounts[path] = (pageCounts[path] || 0) + 1;
          });

          const sortedPages = Object.entries(pageCounts)
            .map(([page, views]) => ({ page: page.charAt(0).toUpperCase() + page.slice(1), views }))
            .sort((a, b) => b.views - a.views)
            .slice(0, 4);

          setAnalytics(prev => ({
            ...prev,
            pageViews: pageViewsCount || 0,
            visitors: Math.floor((pageViewsCount || 0) * 0.4), // Rough estimate for now
            topPages: sortedPages
          }));
        }

        // 3. Recent Activity (Latest Page Views)
        if (recentViews) {
          const activities = recentViews.slice(0, 5).map(v =>
            `User viewed ${v.page_path === '/' ? 'Home' : v.page_path} page`
          );
          setAnalytics(prev => ({ ...prev, recentActivity: activities }));
        }

      } catch (error) {
        console.error("Error fetching analytics:", error);
      }
    };

    fetchRealData();

    // Subscribe to real-time changes
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'page_views',
        },
        () => {
          fetchRealData(); // Refresh on new view
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const stats = [
    {
      label: 'Total Visitors',
      value: analytics.visitors.toLocaleString(),
      icon: <Users className="w-5 h-5 text-blue-400" />,
      change: '+12%',
      color: 'bg-blue-500/10 border-blue-500/20',
      glow: 'shadow-[0_0_15px_rgba(59,130,246,0.3)]'
    },
    {
      label: 'Page Views',
      value: analytics.pageViews.toLocaleString(),
      icon: <Eye className="w-5 h-5 text-purple-400" />,
      change: '+8%',
      color: 'bg-purple-500/10 border-purple-500/20',
      glow: 'shadow-[0_0_15px_rgba(168,85,247,0.3)]'
    },
    {
      label: 'Conversion Rate',
      value: `${analytics.conversionRate}%`,
      icon: <MousePointer className="w-5 h-5 text-emerald-400" />,
      change: '+5%',
      color: 'bg-emerald-500/10 border-emerald-500/20',
      glow: 'shadow-[0_0_15px_rgba(16,185,129,0.3)]'
    },
    {
      label: 'Avg. Time on Site',
      value: analytics.avgTimeOnSite,
      icon: <Clock className="w-5 h-5 text-orange-400" />,
      change: '+15%',
      color: 'bg-orange-500/10 border-orange-500/20',
      glow: 'shadow-[0_0_15px_rgba(249,115,22,0.3)]'
    }
  ];

  return (
    <div className="bg-black/40 backdrop-blur-xl border border-white/10 p-8 rounded-3xl shadow-2xl relative overflow-hidden group hover:border-white/20 transition-all duration-500">
      {/* Premium Background Effects */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-blue-500/10 rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2 pointer-events-none"></div>
      <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-500/10 rounded-full blur-[80px] translate-y-1/2 -translate-x-1/2 pointer-events-none"></div>
      <div className="absolute inset-0 bg-grid-white/[0.02] pointer-events-none"></div>

      <div className="flex items-center justify-between mb-8 relative z-10">
        <div>
          <h3 className="text-2xl font-bold text-white flex items-center gap-3">
            <div className="p-2 bg-blue-500/10 rounded-lg border border-blue-500/20">
              <Activity className="w-6 h-6 text-blue-400" />
            </div>
            Live Analytics
          </h3>
          <p className="text-gray-400 text-sm mt-2 ml-1">Real-time performance metrics</p>
        </div>
        <div className="p-2 bg-white/5 rounded-lg border border-white/10 hover:bg-white/10 transition-colors cursor-pointer">
          <BarChart3 className="w-6 h-6 text-blue-400" />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8 relative z-10">
        {stats.map((stat, index) => (
          <div key={index} className={`p-4 rounded-2xl border ${stat.color} bg-black/20 hover:bg-white/5 transition-all duration-300 group/stat`}>
            <div className="flex items-center justify-between mb-3">
              <div className={`p-2 rounded-xl bg-white/5 ${stat.glow} transition-shadow duration-300`}>
                {stat.icon}
              </div>
              <span className="text-xs font-bold text-emerald-400 bg-emerald-400/10 px-2 py-1 rounded-full border border-emerald-400/20">{stat.change}</span>
            </div>
            <div className="text-2xl font-bold text-white mb-1 tracking-tight">{stat.value}</div>
            <div className="text-xs text-gray-400 uppercase tracking-wider font-medium">{stat.label}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 relative z-10">
        <div className="bg-white/[0.03] border border-white/10 rounded-2xl p-6 hover:bg-white/[0.05] transition-colors">
          <h4 className="text-lg font-bold text-white mb-5 flex items-center gap-2">
            <Eye className="w-4 h-4 text-purple-400" />
            Top Performing Pages
          </h4>
          <div className="space-y-3">
            {analytics.topPages.map((page, index) => (
              <div key={index} className="flex items-center justify-between p-3 bg-black/20 rounded-xl border border-white/5 hover:border-purple-500/30 transition-all group/row">
                <span className="font-medium text-gray-300 group-hover/row:text-white transition-colors">{page.page}</span>
                <span className="text-sm text-blue-400 font-mono bg-blue-400/10 px-2 py-0.5 rounded border border-blue-400/20">{page.views} views</span>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white/[0.03] border border-white/10 rounded-2xl p-6 hover:bg-white/[0.05] transition-colors">
          <h4 className="text-lg font-bold text-white mb-5 flex items-center gap-2">
            <TrendingUp className="w-4 h-4 text-emerald-400" />
            Live Activity Feed
          </h4>
          <div className="space-y-3">
            {analytics.recentActivity.map((activity, index) => (
              <div key={index} className="flex items-center space-x-3 p-3 bg-black/20 rounded-xl border border-white/5 hover:border-emerald-500/30 transition-all">
                <div className="relative">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse relative z-10"></div>
                  <div className="absolute inset-0 w-2 h-2 rounded-full bg-emerald-500 blur-sm animate-ping"></div>
                </div>
                <span className="text-sm text-gray-300">{activity}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdvancedAnalytics;

import React, { useState } from 'react';
import { Check, X, Loader2, CreditCard, Download, MessageCircle, Building2, User, Mail, Phone, ShieldCheck } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useRazorpay } from '@/hooks/useRazorpay';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';
import { jsPDF } from 'jspdf';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";

// PLACEHOLDER: Replace with real key
const RAZORPAY_KEY_ID = import.meta.env.VITE_RAZORPAY_KEY_ID || "";

interface CheckoutModalProps {
    isOpen: boolean;
    onClose: () => void;
    plan: {
        name: string;
        monthlyPrice?: number;
        yearlyPrice?: number;
        price?: number; // fallback for one-time
        color?: string;
    };
    billingCycle?: 'monthly' | 'yearly' | 'one-time';
}

const CheckoutModal: React.FC<CheckoutModalProps> = ({ isOpen, onClose, plan, billingCycle = 'monthly' }) => {
    const { loadRazorpay } = useRazorpay();
    const { toast } = useToast();
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [step, setStep] = useState<'details' | 'success'>('details');

    // Order State
    const [promoCode, setPromoCode] = useState("");
    const [discountAmount, setDiscountAmount] = useState(0);
    const [isValidatingPromo, setIsValidatingPromo] = useState(false);
    const [promoMessage, setPromoMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
    const [agreedToTerms, setAgreedToTerms] = useState(false);

    // Client Details
    const [clientName, setClientName] = useState("");
    const [clientEmail, setClientEmail] = useState("");
    const [clientPhone, setClientPhone] = useState("");
    const [companyName, setCompanyName] = useState("");

    // Calculate Price
    const getOriginalPrice = () => {
        if (billingCycle === 'monthly') return plan.monthlyPrice || 0;
        if (billingCycle === 'yearly') return plan.yearlyPrice || 0;
        return plan.price || 0; // One-time plans
    };

    const finalPrice = Math.max(0, getOriginalPrice() - discountAmount);

    // 1. Validate Promo Code
    const verifyPromoCode = async () => {
        if (!promoCode.trim()) return;
        setIsValidatingPromo(true);
        setPromoMessage(null);

        try {
            const { data, error } = await supabase
                .from('promo_codes')
                .select('*')
                .eq('code', promoCode.trim())
                .eq('is_active', true)
                .maybeSingle();

            if (error) {
                console.warn("Supabase error:", error);
                setPromoMessage({ type: 'error', text: "Invalid code." });
                setDiscountAmount(0);
                return;
            }

            if (!data) {
                setPromoMessage({ type: 'error', text: "Invalid or expired code." });
                setDiscountAmount(0);
            } else {
                // Calculate Discount
                let calculatedDiscount = 0;
                const price = getOriginalPrice();

                if (data.discount_type === 'flat') {
                    calculatedDiscount = Number(data.discount_value);
                } else if (data.discount_type === 'percent') {
                    calculatedDiscount = (price * Number(data.discount_value)) / 100;
                }

                // Check Min Order
                if (data.min_order_value && price < data.min_order_value) {
                    setPromoMessage({ type: 'error', text: `Minimum order value of ₹${data.min_order_value} required.` });
                    setDiscountAmount(0);
                    return;
                }

                setDiscountAmount(calculatedDiscount);
                setPromoMessage({ type: 'success', text: `Coupon applied! Saved ₹${calculatedDiscount.toLocaleString()}` });
            }
        } catch (err) {
            setPromoMessage({ type: 'error', text: "Error verifying code." });
        } finally {
            setIsValidatingPromo(false);
        }
    };

    // 2. Generate PDF Invoice
    const generateInvoice = () => {
        const doc = new jsPDF();

        // Header
        doc.setFontSize(20);
        doc.setTextColor(147, 51, 234); // Purple
        doc.text("YourWebPartner", 20, 20);

        doc.setFontSize(10);
        doc.setTextColor(100);
        doc.text("Invoice / Receipt", 20, 30);
        doc.text(`Date: ${new Date().toLocaleDateString()}`, 20, 35);

        // Client Details
        doc.setFontSize(12);
        doc.setTextColor(0);
        doc.text("Bill To:", 20, 50);
        doc.setFontSize(10);
        doc.text(companyName, 20, 56);
        doc.text(clientName, 20, 61);
        doc.text(clientEmail, 20, 66);
        doc.text(clientPhone, 20, 71);

        // Order Details
        doc.line(20, 80, 190, 80);
        doc.text("Description", 20, 86);
        doc.text("Amount", 160, 86);
        doc.line(20, 90, 190, 90);

        doc.text(`${plan.name} Plan (${billingCycle})`, 20, 100);
        doc.text(`Rs. ${getOriginalPrice().toLocaleString()}`, 160, 100);

        if (discountAmount > 0) {
            doc.setTextColor(22, 163, 74); // Green
            doc.text(`Discount (${promoCode})`, 20, 110);
            doc.text(`- Rs. ${discountAmount.toLocaleString()}`, 160, 110);
            doc.setTextColor(0);
        }

        doc.line(20, 120, 190, 120);
        doc.setFontSize(12);
        doc.text("Total Paid", 120, 130);
        doc.text(`Rs. ${finalPrice.toLocaleString()}`, 160, 130);

        // Footer
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text("Thank you for your business. For support, contact admin@yourwebpartner.com", 20, 280);

        doc.save(`Invoice_${companyName.replace(/\s+/g, '_')}_${new Date().getTime()}.pdf`);
    };

    // 3. WhatsApp Link
    const openWhatsApp = () => {
        const message = `Hi, I just purchased the ${plan.name} Plan for ${companyName}. I'd like to confirm the next steps.`;
        const url = `https://wa.me/919876543210?text=${encodeURIComponent(message)}`; // Replace with real support number
        window.open(url, '_blank');
    };

    // 4. Payment Trigger
    const handlePayment = async () => {
        if (!clientName || !clientEmail || !clientPhone || !companyName) {
            toast({ title: "Start Up Error", description: "All fields including Company Name are required.", variant: "destructive" });
            return;
        }

        setIsLoading(true);
        const isLoaded = await loadRazorpay();
        if (!isLoaded) {
            toast({ title: "Error", description: "Payment gateway failed to load.", variant: "destructive" });
            setIsLoading(false);
            return;
        }

        const options = {
            key: RAZORPAY_KEY_ID,
            amount: finalPrice * 100, // Paisa
            currency: "INR",
            name: "YourWebPartner",
            description: `Payment for ${plan.name}`,
            image: "https://yourwebpartner.com/logo.png", // Ensure this exists or use placeholder
            prefill: { name: clientName, email: clientEmail, contact: clientPhone },
            notes: {
                plan: plan.name,
                company: companyName,
                promo_code: promoCode
            },
            handler: async function (response: any) {
                try {
                    // Backend Verification
                    const { data, error } = await supabase.functions.invoke('verify-payment', {
                        body: {
                            razorpay_payment_id: response.razorpay_payment_id,
                            razorpay_order_id: response.razorpay_order_id || response.razorpay_payment_id,
                            razorpay_signature: response.razorpay_signature,
                            plan_name: plan.name,
                            amount: finalPrice,
                            currency: "INR",
                            promo_code: promoCode,
                            customer_email: clientEmail,
                            customer_name: clientName,
                            customer_phone: clientPhone,
                            company_name: companyName // New Field
                        }
                    });

                    if (error) throw error;
                    if (data && data.error) throw new Error(data.error);

                    // Redirect to Success Page
                    onClose();
                    navigate('/payment-success', {
                        state: {
                            paymentId: response.razorpay_payment_id,
                            orderId: response.razorpay_order_id,
                            amount: finalPrice,
                            planName: plan.name,
                            companyName: companyName,
                            date: new Date().toLocaleDateString()
                        }
                    });

                } catch (err: any) {
                    console.error("Backend Verification Failed:", err);
                    onClose();
                    navigate('/payment-failed', {
                        state: {
                            error: err.message || "Payment verification failed",
                            planName: plan.name
                        }
                    });
                }
            },
            theme: { color: "#9333ea" }
        };

        const rzp = new (window as any).Razorpay(options);
        rzp.open();
        setIsLoading(false);
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="sm:max-w-xl bg-[#0a0a0a] border-white/10 text-white p-0 overflow-hidden">
                {step === 'details' ? (
                    <>
                        <DialogHeader className="p-6 pb-2">
                            <div className="flex justify-between items-start">
                                <div>
                                    <DialogTitle className="text-2xl font-bold">Secure Checkout</DialogTitle>
                                    <DialogDescription className="text-gray-400 mt-1">
                                        Complete your purchase for {plan.name}
                                    </DialogDescription>
                                </div>
                                <div className="bg-purple-500/10 px-3 py-1 rounded-full border border-purple-500/20 text-xs font-medium text-purple-400 flex items-center gap-1">
                                    <ShieldCheck className="w-3 h-3" /> Secure SSL
                                </div>
                            </div>
                        </DialogHeader>

                        <div className="p-6 py-2 space-y-4 max-h-[60vh] overflow-y-auto custom-scrollbar">
                            {/* Plan Summary */}
                            <div className="bg-white/5 rounded-xl p-4 border border-white/10 flex justify-between items-center">
                                <div className="flex gap-3 items-center">
                                    <div className={`w-10 h-10 rounded-lg bg-${plan.color || 'blue'}-500/20 flex items-center justify-center text-${plan.color || 'blue'}-400`}>
                                        <CreditCard className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <h4 className="font-bold">{plan.name}</h4>
                                        <p className="text-xs text-gray-400 capitalize">{billingCycle}</p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <p className="font-bold text-lg">₹{finalPrice.toLocaleString()}</p>
                                    {discountAmount > 0 && <p className="text-xs text-green-400 line-through">₹{getOriginalPrice().toLocaleString()}</p>}
                                </div>
                            </div>

                            {/* Form Fields */}
                            <div className="space-y-3">
                                <div className="grid grid-cols-2 gap-3">
                                    <div className="space-y-1">
                                        <Label className="text-xs font-semibold text-gray-500">FULL NAME <span className="text-red-500">*</span></Label>
                                        <div className="relative">
                                            <User className="absolute left-3 top-2.5 w-4 h-4 text-gray-500" />
                                            <Input placeholder="John Doe" className="pl-9 bg-white/5 border-white/10" value={clientName} onChange={e => setClientName(e.target.value)} />
                                        </div>
                                    </div>
                                    <div className="space-y-1">
                                        <Label className="text-xs font-semibold text-gray-500">COMPANY NAME <span className="text-red-500">*</span></Label>
                                        <div className="relative">
                                            <Building2 className="absolute left-3 top-2.5 w-4 h-4 text-gray-500" />
                                            <Input placeholder="Acme Inc." className="pl-9 bg-white/5 border-white/10" value={companyName} onChange={e => setCompanyName(e.target.value)} />
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-1">
                                    <Label className="text-xs font-semibold text-gray-500">EMAIL ADDRESS <span className="text-red-500">*</span></Label>
                                    <div className="relative">
                                        <Mail className="absolute left-3 top-2.5 w-4 h-4 text-gray-500" />
                                        <Input type="email" placeholder="john@company.com" className="pl-9 bg-white/5 border-white/10" value={clientEmail} onChange={e => setClientEmail(e.target.value)} />
                                    </div>
                                </div>

                                <div className="space-y-1">
                                    <Label className="text-xs font-semibold text-gray-500">PHONE NUMBER <span className="text-red-500">*</span></Label>
                                    <div className="relative">
                                        <Phone className="absolute left-3 top-2.5 w-4 h-4 text-gray-500" />
                                        <Input type="tel" placeholder="+91 98765 43210" className="pl-9 bg-white/5 border-white/10" value={clientPhone} onChange={e => setClientPhone(e.target.value)} />
                                    </div>
                                </div>
                            </div>

                            {/* Promo Code */}
                            <div className="pt-2">
                                <div className="flex gap-2">
                                    <Input
                                        placeholder="Have a promo code?"
                                        className="bg-white/5 border-white/10 focus:ring-purple-500/50"
                                        value={promoCode}
                                        onChange={e => setPromoCode(e.target.value.toUpperCase())}
                                    />
                                    <Button variant="outline" className="border-white/20 hover:bg-white/10" onClick={verifyPromoCode} disabled={!promoCode || isValidatingPromo}>
                                        {isValidatingPromo ? <Loader2 className="animate-spin w-4 h-4" /> : "Apply"}
                                    </Button>
                                </div>
                                {promoMessage && (
                                    <p className={`text-xs mt-1 flex items-center gap-1 ${promoMessage.type === 'success' ? 'text-green-400' : 'text-red-400'}`}>
                                        {promoMessage.type === 'success' ? <Check className="w-3 h-3" /> : <X className="w-3 h-3" />}
                                        {promoMessage.text}
                                    </p>
                                )}
                            </div>

                            {/* Terms */}
                            <div className="flex items-start space-x-2 pt-2">
                                <Checkbox id="terms" checked={agreedToTerms} onCheckedChange={(c) => setAgreedToTerms(c as boolean)} className="data-[state=checked]:bg-purple-600 border-white/20 mt-1" />
                                <Label htmlFor="terms" className="text-xs text-gray-400 leading-snug">
                                    I agree to the <a href="/terms" target="_blank" className="text-purple-400 underline">Terms</a> & <a href="/privacy" target="_blank" className="text-purple-400 underline">Privacy Policy</a>.
                                    Invoice will be sent to your email.
                                </Label>
                            </div>
                        </div>

                        <DialogFooter className="p-6 pt-2">
                            <Button
                                className="w-full h-12 bg-gradient-to-r from-purple-600 to-pink-600 hover:brightness-110 transition-all font-bold text-lg shadow-lg shadow-purple-900/20"
                                onClick={handlePayment}
                                disabled={isLoading || !agreedToTerms}
                            >
                                {isLoading ? <Loader2 className="animate-spin" /> : "Complete Payment"}
                            </Button>
                        </DialogFooter>
                    </>
                ) : (
                    <div className="p-8 text-center flex flex-col items-center justify-center min-h-[400px]">
                        <div className="w-20 h-20 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mb-6 animate-in zoom-in duration-300">
                            <Check className="w-10 h-10" />
                        </div>
                        <h2 className="text-3xl font-bold text-white mb-2">Payment Successful!</h2>
                        <p className="text-gray-400 mb-8 max-w-sm">
                            Thank you for your purchase. A confirmation email has been sent to {clientEmail}.
                        </p>

                        <div className="w-full space-y-3">
                            <Button onClick={generateInvoice} variant="outline" className="w-full h-12 border-white/20 hover:bg-white/10 gap-2">
                                <Download className="w-5 h-5 text-blue-400" /> Download Invoice
                            </Button>

                            <Button onClick={openWhatsApp} className="w-full h-12 bg-[#25D366] hover:bg-[#128C7E] text-white gap-2 font-bold">
                                <MessageCircle className="w-5 h-5" /> Confirm on WhatsApp
                            </Button>

                            <Button onClick={onClose} variant="ghost" className="text-gray-500 hover:text-white mt-2">
                                Close Window
                            </Button>
                        </div>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
};

export default CheckoutModal;

import React, { useState, useEffect, useRef } from 'react';
import { Mail, Phone, MapPin, Send, Sparkles, MessageSquare, ArrowRight } from 'lucide-react';
import emailjs from '@emailjs/browser';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';

// --- EMAILJS CONFIGURATION ---
// REPLACE THESE WITH YOUR ACTUAL KEYS FROM https://dashboard.emailjs.com/
const EMAILJS_SERVICE_ID = 'service_x1z9s5a';
const EMAILJS_TEMPLATE_ID = 'template_ohrxkmi';
const EMAILJS_PUBLIC_KEY = 'ljyKjgp1kdNLSnnPI';

const Contact = () => {
  const formRef = useRef<HTMLFormElement>(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    service: '',
    message: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { toast } = useToast();

  // Check for URL parameters to pre-fill the form
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const serviceParam = urlParams.get('service');
    const packageParam = urlParams.get('package');
    const typeParam = urlParams.get('type');

    if (serviceParam) {
      let serviceValue = '';
      let messageValue = '';

      // Map URL parameters to form values
      if (serviceParam === 'basic-website') {
        serviceValue = 'Basic Website Package';
        messageValue = `I'm interested in the Basic Website Package${packageParam ? ` (${packageParam})` : ''}. Please provide more details and a quote.`;
      } else if (serviceParam === 'professional-website') {
        serviceValue = 'Professional Website Package';
        messageValue = `I'm interested in the Professional Website Package${packageParam ? ` (${packageParam})` : ''}. Please provide more details and a quote.`;
      } else if (serviceParam === 'enterprise-website') {
        serviceValue = 'Enterprise Website Package';
        messageValue = `I'm interested in the Enterprise Website Package${packageParam ? ` (${packageParam})` : ''}. Please provide more details and a quote.`;
      } else if (serviceParam === 'custom-quote') {
        serviceValue = 'Custom Development';
        messageValue = `I need a custom quote for ${packageParam || 'enterprise'} solutions. Please contact me to discuss my specific requirements.`;
      } else if (serviceParam === 'consultation') {
        serviceValue = 'Free Consultation';
        if (typeParam === 'schedule') {
          messageValue = 'I would like to schedule a consultation to discuss my project requirements.';
        } else {
          messageValue = 'I would like a free consultation and quote for my project.';
        }
      }

      setFormData(prev => ({
        ...prev,
        service: serviceValue,
        message: messageValue
      }));
    }
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);

    // --- REAL SEND MODE ---
    try {
      if (!formRef.current) return;

      // Define params BEFORE using them
      const templateParams = {
        to_name: 'Admin',
        from_name: formData.name,
        name: formData.name,
        reply_to: formData.email,
        email: formData.email,
        phone: formData.phone,
        service: formData.service,
        message: formData.message,
      };

      // Run Supabase and EmailJS in parallel to speed up "Sending..."
      const [dbResult, emailResult] = await Promise.allSettled([
        // 1. Save to Database
        supabase.from('contact_submissions').insert([{
          name: formData.name,
          email: formData.email,
          phone: formData.phone,
          service: formData.service,
          message: formData.message
        }]),
        // 2. Send via EmailJS
        emailjs.send(
          EMAILJS_SERVICE_ID,
          EMAILJS_TEMPLATE_ID,
          templateParams,
          EMAILJS_PUBLIC_KEY
        )
      ]);

      // Check results
      if (dbResult.status === 'rejected') {
        console.error("Supabase Save Error:", dbResult.reason);
      }
      if (emailResult.status === 'rejected') {
        console.error("EmailJS Error:", emailResult.reason);
        toast({
          title: "Opening WhatsApp...",
          description: "Proceeding to WhatsApp to complete your inquiry.",
        });
      } else {
        console.log('EmailJS Success:', (emailResult as PromiseFulfilledResult<any>).value.text);
        toast({
          title: "Message Sent Successfully! 🎉",
          description: "We have received your inquiry. Opening WhatsApp...",
        });
      }

      // --- WhatsApp Integration ---
      const waMessage = `*New Inquiry from Website* 🚀%0A%0A` +
        `*Name:* ${formData.name}%0A` +
        `*Email:* ${formData.email}%0A` +
        `*Phone:* ${formData.phone}%0A` +
        `*Service:* ${formData.service}%0A` +
        `*Message:* ${formData.message}`;

      const waUrl = `https://wa.me/918160103379?text=${waMessage}`;

      // Open WhatsApp in a new tab
      window.open(waUrl, '_blank');

      // Reset form
      setFormData({
        name: '',
        email: '',
        phone: '',
        service: '',
        message: ''
      });

    } catch (error: any) {
      console.error('Submission Error:', error);
      // SHOW REAL ERROR TO USER
      toast({
        title: "Email Failed (Check Console)",
        description: `Error: ${error?.text || error?.message || JSON.stringify(error)}. Opening WhatsApp...`,
        variant: "destructive",
        duration: 5000,
      });

      // Fallback: Open WhatsApp even if error occurs
      const messageText = `*New Inquiry from Website* 🚀\n\n` +
        `*Name:* ${formData.name}\n` +
        `*Email:* ${formData.email}\n` +
        `*Phone:* ${formData.phone}\n` +
        `*Service:* ${formData.service}\n` +
        `*Message:* ${formData.message}`;

      const waUrl = `https://wa.me/918160103379?text=${encodeURIComponent(messageText)}`;

      // DOM-based redirection to bypass popup blockers
      const link = document.createElement('a');
      link.href = waUrl;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <section id="contact" className="py-32 bg-background relative overflow-hidden">
      {/* Animated Background Elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="blob absolute top-0 left-0 w-[500px] h-[500px] bg-purple-900/10 rounded-full blur-[120px] mix-blend-screen animate-pulse"></div>
        <div className="blob absolute bottom-0 right-0 w-[400px] h-[400px] bg-blue-900/10 rounded-full blur-[100px] mix-blend-screen animate-pulse animation-delay-2000"></div>
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-purple-900/5 via-transparent to-transparent"></div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-20">
          <h2 className="text-5xl md:text-7xl font-bold text-white mb-6">
            Get In <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">Touch</span>
          </h2>
          <p className="text-2xl text-gray-400 max-w-3xl mx-auto font-light">
            Ready to start your web project? We're here to help you grow.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-5 gap-12 lg:gap-20">
          {/* Contact Information Cards */}
          <div className="lg:col-span-2 space-y-8">
            <div className="relative group">
              <div className="absolute inset-0 bg-gradient-to-r from-blue-600 to-purple-600 rounded-3xl blur opacity-20 group-hover:opacity-40 transition duration-500"></div>
              <div className="relative bg-white/5 backdrop-blur-xl border border-white/10 p-8 rounded-3xl hover:border-white/20 transition-all duration-300">
                <h3 className="text-2xl font-bold text-white mb-8">Contact Info</h3>

                <div className="space-y-8">
                  <a href="mailto:yourwebpartner1@gmail.com" className="flex items-center space-x-6 group/item cursor-pointer">
                    <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center group-hover/item:bg-blue-500/20 transition-all duration-300 border border-blue-500/20">
                      <Mail className="w-6 h-6 text-blue-400" />
                    </div>
                    <div>
                      <p className="text-sm text-gray-400 uppercase tracking-wider font-semibold mb-1">Email Us</p>
                      <p className="text-white font-medium text-lg group-hover/item:text-blue-400 transition-colors">yourwebpartner1@gmail.com</p>
                    </div>
                  </a>

                  <a href="tel:+916300371553" className="flex items-center space-x-6 group/item cursor-pointer">
                    <div className="w-14 h-14 bg-green-500/10 rounded-2xl flex items-center justify-center group-hover/item:bg-green-500/20 transition-all duration-300 border border-green-500/20">
