import React, { useState } from 'react';
import { Send, CheckCircle } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';

const Newsletter = () => {
  const [email, setEmail] = useState('');
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;

    setIsLoading(true);

    try {
      const { error } = await supabase
        .from('subscribers')
        .insert([{ email }]);

      if (error) {
        // specialized error handling for duplicates if needed
        if (error.code === '23505') { // unique_violation
          toast({
            title: "Already Subscribed",
            description: "This email is already on our list!",
            variant: "default"
          });
          setIsSubscribed(true); // Treat as success
          return;
        }
        throw error;
      }

      setIsSubscribed(true);
      setEmail('');
      toast({
        title: "Success!",
        description: "You've been added to our newsletter.",
      });

    } catch (error: any) {
      console.error('Newsletter error:', error);
      toast({
        title: "Error",
        description: "Failed to subscribe. Please try again.",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  if (isSubscribed) {
    return (
      <div className="bg-white/10 backdrop-blur-md p-8 rounded-2xl text-center border border-green-500/20 shadow-lg">
        <CheckCircle className="w-16 h-16 text-green-400 mx-auto mb-4 animate-bounce" />
        <h3 className="text-2xl font-bold text-white mb-2">Thank You!</h3>
        <p className="text-gray-300">
          You've successfully subscribed to our newsletter. Get ready for amazing web development tips!
        </p>
        <button
          onClick={() => setIsSubscribed(false)}
          className="mt-4 text-green-400 hover:text-green-300 font-medium transition-colors"
        >
          Subscribe another email
        </button>
      </div>
    );
  }

  return (
    <div className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-600 p-8 rounded-2xl text-white relative overflow-hidden">
      <div className="absolute inset-0 bg-black opacity-10"></div>
      <div className="relative z-10">
        <h3 className="text-3xl font-bold mb-4 text-center">
          Stay Updated with Web Trends
        </h3>
        <p className="text-lg mb-6 text-center opacity-90">
          Get weekly tips, tutorials, and insights delivered straight to your inbox
        </p>

        <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row gap-4 max-w-md mx-auto">
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Enter your email address"
            className="flex-1 px-4 py-3 rounded-full text-gray-900 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-white"
            required
          />
          <button
            type="submit"
            disabled={isLoading}
            className="bg-white text-purple-600 px-6 py-3 rounded-full font-semibold hover:shadow-lg transition-all duration-300 flex items-center justify-center space-x-2 disabled:opacity-50"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-purple-600 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <>
                <Send className="w-5 h-5" />
                <span>Subscribe</span>
              </>
            )}
          </button>
        </form>

        <div className="flex justify-center items-center space-x-6 mt-6 text-sm opacity-80">
          <span>✓ Weekly web tips</span>
          <span>✓ No spam ever</span>
          <span>✓ Unsubscribe anytime</span>
        </div>
      </div>
    </div>
  );
};

export default Newsletter;

import React, { useRef } from 'react';
import { Users, Award, Clock, Heart } from 'lucide-react';
import { useGSAP } from '@gsap/react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { Button } from './ui/button';

gsap.registerPlugin(ScrollTrigger);

import { supabase } from '@/integrations/supabase/client';
import { useState, useEffect } from 'react';

// ... (keep existing imports)

const Stats = () => {
  const containerRef = useRef<HTMLElement>(null);
  const [stats, setStats] = useState<any[]>([]);

  // Icon mapping for dynamic rendering
  const IconMap: Record<string, any> = {
    Users, Award, Clock, Heart
  };

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const { data, error } = await supabase
          .from('stats')
          .select('*')
          .order('sort_order', { ascending: true });

        if (error) throw error;

        if (data) {
          const formattedStats = data.map(stat => ({
            ...stat,
            icon: IconMap[stat.icon_name] ? React.createElement(IconMap[stat.icon_name], { className: "w-8 h-8 text-white" }) : null,
            bgCtx: stat.bg_color, // Map DB column to component prop
            shadow: stat.shadow_color
          }));
          setStats(formattedStats);
        }
      } catch (error) {
        console.error('Error fetching stats:', error);
      }
    };

    fetchStats();
  }, []);

  useGSAP(() => {
    if (stats.length === 0) return; // Wait for stats to load before animating

    // Animate the main text card
    gsap.from(".main-card", {
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top 80%",
        toggleActions: "play none none none"
      },
      x: -50,
      opacity: 0,
      duration: 1,
      ease: "power3.out"
    });

    // Animate the stat cards on the right
    gsap.from(".stat-card", {
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top 80%",
        toggleActions: "play none none none"
      },
      scale: 0.8,
      opacity: 0,
      stagger: 0.1,
      duration: 0.6,
      ease: "back.out(1.7)"
    });
  }, { scope: containerRef, dependencies: [stats] }); // Re-run animation when stats load

  return (
    <section ref={containerRef} className="py-24 bg-background relative z-10 overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col lg:flex-row gap-8 items-stretch">

          {/* Left Column: Main Text Card */}
          <div className="lg:w-1/2 main-card bg-white rounded-[2.5rem] p-10 shadow-xl shadow-gray-200/50 flex flex-col justify-center">
            <h2 className="text-4xl lg:text-5xl font-bold text-slate-900 mb-6 leading-tight">
              Crafting Digital <span className="text-orange-500">Masterpieces</span>
            </h2>
            <p className="text-slate-600 mb-6 leading-relaxed">
              Founded with a vision to revolutionize the digital landscape,
              we combine cutting-edge technology with creative excellence
              to deliver solutions that don't just meet expectations—they
              exceed them.
            </p>
            <p className="text-slate-600 mb-8 leading-relaxed">
              Our team of passionate designers and developers work tirelessy
              to ensure every project is a testament to innovation,
              quality, and client satisfaction.
            </p>
            <div>
              <Button className="bg-[#D9264F] hover:bg-[#b01e3f] text-white rounded-full px-8 py-6 text-lg font-semibold shadow-lg shadow-pink-500/30 transition-all hover:scale-105">
                Learn More About Us
              </Button>
            </div>
          </div>

          {/* Right Column: Stats Grid */}
          <div className="lg:w-1/2 grid grid-cols-2 gap-6">
            {stats.map((stat, index) => (
              <div
                key={index}
                className={`stat-card bg-${index === 2 ? 'green-50' : (index === 3 ? 'red-50' : (index === 0 ? 'blue-50' : 'purple-50'))} bg-white rounded-[2rem] p-6 flex flex-col items-center justify-center text-center shadow-lg shadow-gray-100/50 hover:shadow-xl transition-all duration-300 hover:-translate-y-1`}
              >
                <div className={`mb-4 w-16 h-16 rounded-full ${stat.bgCtx} flex items-center justify-center shadow-lg ${stat.shadow}`}>
                  {stat.icon}
                </div>
                <h3 className={`text-3xl font-bold mb-2 ${index === 0 ? 'text-blue-500' :
                  index === 1 ? 'text-fuchsia-500' :
                    index === 2 ? 'text-emerald-500' : 'text-rose-500'
                  }`}>
                  {stat.value}
                </h3>
                <p className="text-slate-600 font-semibold text-sm sm:text-base">{stat.label}</p>
              </div>
            ))}
          </div>

        </div>
      </div>
    </section>
  );
};

