        { title: 'Bistro Reserve', category: 'Food', image_url: 'https://images.unsplash.com/photo-1559339352-11d035aa65de?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', description: 'Online ordering and table booking system for a restaurant chain.', tech: ['React', 'Express', 'MongoDB'], client: 'Bistro Chain', duration: '3 months', year: '2024', color: 'orange' },
        { title: 'Coffee Culture', category: 'Food', image_url: 'https://images.unsplash.com/photo-1497935586351-b67a49e012bf?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', description: 'Subscription management platform for specialty coffee beans.', tech: ['Shopify Liquid', 'Js', 'Recharge'], client: 'Coffee Culture', duration: '2 months', 'year': '2023', color: 'brown' },
        { title: 'FarmToTable', category: 'Food', image_url: 'https://images.unsplash.com/photo-1466637574441-749b8f19452f?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', description: 'Marketplace connecting local organic farmers directly with consumers.', tech: ['Next.js', 'Stripe', 'PostgreSQL'], client: 'Local Farms', duration: '4 months', year: '2023', color: 'green' },
        { title: 'CleanOcean Initiative', category: 'Non-Profit', image_url: 'https://images.unsplash.com/photo-1484291470158-b8f8d608850d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', description: 'Donation and awareness platform for ocean conservation efforts.', tech: ['WordPress', 'React', 'Donation API'], client: 'Ocean NGO', 'duration': '2 months', 'year': '2024', color: 'cyan' },
        { title: 'EduForAll', category: 'Non-Profit', image_url: 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', description: 'Volunteer management system for rural education programs.', tech: ['React', 'Firebase', 'Google Maps'], client: 'Edu Foundation', duration: '3 months', 'year': '2023', color: 'yellow' }
    ];

    const handleSeed = async () => {
        if (!confirm('This will insert 30+ projects. Continue?')) return;
        try {
            const { error } = await supabase.from('projects').insert(DEFAULT_PROJECTS);
            if (error) throw error;
            toast({ title: "Success", description: "All projects seeded successfully!" });
            fetchProjects();
        } catch (error: any) {
            console.error('Seed error:', error);
            toast({ title: "Error", description: error.message, variant: "destructive" });
        }
    };

    useEffect(() => {
        fetchProjects();
    }, []);

    const fetchProjects = async () => {
        try {
            const { data, error } = await supabase
                .from('projects')
                .select('*')
                .order('created_at', { ascending: false });

            if (error) throw error;
            setProjects((data || []) as Project[]);
        } catch (error) {
            console.error('Error fetching projects:', error);
            toast({
                title: "Error",
                description: "Failed to load projects",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!currentProject.title || !currentProject.category || !currentProject.image_url) {
            toast({
                title: "Missing fields",
                description: "Please fill in all required fields (Title, Category, Image URL)",
                variant: "destructive"
            });
            return;
        }

        try {
            const projectData = {
                title: currentProject.title,
                category: currentProject.category,
                image_url: currentProject.image_url,
                description: currentProject.description || '',
                tech: currentProject.tech || [],
                client: currentProject.client || '',
                duration: currentProject.duration || '',
                year: currentProject.year || new Date().getFullYear().toString(),
                color: currentProject.color || 'blue',
                link: currentProject.link || ''
            };

            if (currentProject.id) {
                const { error } = await supabase
                    .from('projects')
                    .update(projectData)
                    .eq('id', currentProject.id);
                if (error) throw error;
                toast({ title: "Success", description: "Project updated successfully" });
            } else {
                const { error } = await supabase
                    .from('projects')
                    .insert([projectData]);
                if (error) throw error;
                toast({ title: "Success", description: "Project created successfully" });
            }

            setIsEditing(false);
            setCurrentProject({ tech: [], color: 'blue' });
            fetchProjects();
        } catch (error: any) {
            console.error('Error saving project:', error);
            toast({
                title: "Error",
                description: error.message || "Failed to save project",
                variant: "destructive"
            });
        }
    };

    const handleDelete = async (id: number) => {
        try {
            const { error } = await supabase
                .from('projects')
                .delete()
                .eq('id', id);
            if (error) throw error;
            toast({ title: "Success", description: "Project deleted" });
            fetchProjects();
        } catch (error) {
            console.error('Error deleting project:', error);
            toast({
                title: "Error",
                description: "Failed to delete project",
                variant: "destructive"
            });
        }
    };

    const addTech = (tag: string) => {
        if (tag && !currentProject.tech?.includes(tag)) {
            setCurrentProject({
                ...currentProject,
                tech: [...(currentProject.tech || []), tag]
            });
        }
    };

    const removeTech = (tagToRemove: string) => {
        setCurrentProject({
            ...currentProject,
            tech: currentProject.tech?.filter(tag => tag !== tagToRemove)
        });
    };

    return (
        <div className="p-6 text-white space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-3xl font-bold bg-gradient-to-r from-blue-400 to-purple-400 bg-clip-text text-transparent">
                    Projects Manager
                </h2>
                <button
                    onClick={handleSeed}
                    className="flex items-center space-x-2 px-4 py-2 bg-green-600 hover:bg-green-700 rounded-lg transition-colors mr-2"
                >
                    <Plus className="w-4 h-4" />
                    <span>Seed DB</span>
                </button>
                <button
                    onClick={() => {
                        setCurrentProject({ tech: [], color: 'blue' });
                        setIsEditing(true);
                    }}
                    className="flex items-center space-x-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 rounded-lg transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    <span>Add Project</span>
                </button>
            </div>

            {isEditing && (
                <div className="bg-white/5 backdrop-blur-sm border border-white/10 p-6 rounded-xl space-y-4 animate-in fade-in slide-in-from-top-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Project Title *</label>
                            <input
                                type="text"
                                value={currentProject.title || ''}
                                onChange={e => setCurrentProject({ ...currentProject, title: e.target.value })}
                                className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                placeholder="E-commerce Store"
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Category *</label>
                            <input
                                type="text"
                                value={currentProject.category || ''}
                                onChange={e => setCurrentProject({ ...currentProject, category: e.target.value })}
                                className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                placeholder="Online Retail"
                            />
                        </div>

                        <div className="space-y-2 col-span-2">
                            <label className="text-sm text-gray-400">Description</label>
                            <textarea
                                value={currentProject.description || ''}
                                onChange={e => setCurrentProject({ ...currentProject, description: e.target.value })}
                                className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none h-24"
                                placeholder="Project description..."
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Image URL *</label>
                            <div className="flex gap-2">
                                <ImageIcon className="w-5 h-5 text-gray-400 self-center" />
                                <input
                                    type="text"
                                    value={currentProject.image_url || ''}
                                    onChange={e => setCurrentProject({ ...currentProject, image_url: e.target.value })}
                                    className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                    placeholder="https://..."
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Project Link</label>
                            <div className="flex gap-2">
                                <ExternalLink className="w-5 h-5 text-gray-400 self-center" />
                                <input
                                    type="text"
                                    value={currentProject.link || ''}
                                    onChange={e => setCurrentProject({ ...currentProject, link: e.target.value })}
                                    className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                    placeholder="https://..."
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Client</label>
                            <input
                                type="text"
                                value={currentProject.client || ''}
                                onChange={e => setCurrentProject({ ...currentProject, client: e.target.value })}
                                className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                placeholder="TechMart"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm text-gray-400">Tech Stack (Press Enter)</label>
                            <input
                                type="text"
                                onKeyDown={e => {
                                    if (e.key === 'Enter') {
                                        e.preventDefault();
                                        addTech(e.currentTarget.value);
                                        e.currentTarget.value = '';
                                    }
                                }}
                                className="w-full bg-black/20 border border-white/10 rounded-lg p-2 focus:border-purple-500 outline-none"
                                placeholder="React, Node.js..."
                            />
                            <div className="flex flex-wrap gap-2 mt-2">
                                {currentProject.tech?.map(tag => (
                                    <span key={tag} className="px-2 py-1 bg-purple-500/20 text-purple-300 rounded text-xs flex items-center gap-1">
                                        {tag}
                                        <button onClick={() => removeTech(tag)}><X className="w-3 h-3 hover:text-white" /></button>
                                    </span>
                                ))}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-sm text-gray-400">Duration</label>
                                <input
                                    type="text"
                                    value={currentProject.duration || ''}
                                    onChange={e => setCurrentProject({ ...currentProject, duration: e.target.value })}
                                    className="w-full bg-black/20 border border-white/10 rounded-lg p-2"
                                    placeholder="3 months"
                                />
                            </div>
                            <div>
                                <label className="text-sm text-gray-400">Theme Color</label>
                                <select
                                    value={currentProject.color || 'blue'}
                                    onChange={e => setCurrentProject({ ...currentProject, color: e.target.value })}
                                    className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white"
                                >
                                    <option value="blue">Blue</option>
                                    <option value="purple">Purple</option>
                                    <option value="green">Green</option>
                                    <option value="red">Red</option>
                                    <option value="pink">Pink</option>
                                    <option value="yellow">Yellow</option>
                                    <option value="cyan">Cyan</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end space-x-2 pt-4 border-t border-white/10">
                        <button
                            onClick={() => setIsEditing(false)}
                            className="px-4 py-2 hover:bg-white/5 rounded-lg transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleSave}
                            className="flex items-center space-x-2 px-6 py-2 bg-green-600 hover:bg-green-700 rounded-lg transition-colors"
                        >
                            <Save className="w-4 h-4" />
                            <span>Save Project</span>
                        </button>
                    </div>
                </div>
            )}

            {loading ? (
                <div className="text-center py-20 text-gray-400">Loading projects...</div>
            ) : projects.length === 0 ? (
                <div className="text-center py-20 bg-white/5 rounded-2xl border border-white/10">
                    <ImageIcon className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold mb-2">No Projects Found</h3>
                    <p className="text-gray-400">Start by adding your first project to the portfolio.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {projects.map((project) => (
                        <div key={project.id} className="group relative bg-white/5 border border-white/10 rounded-xl overflow-hidden hover:border-purple-500/50 transition-all">
                            <div className="aspect-video overflow-hidden">
                                <img src={project.image_url} alt={project.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                            </div>
                            <div className="p-4">
                                <div className="flex justify-between items-start mb-2">
                                    <div>
                                        <span className={`inline-block px-2 py-1 text-xs rounded-full mb-2 bg-${project.color}-500/10 text-${project.color}-400 border border-${project.color}-500/20`}>
                                            {project.category}
                                        </span>
                                        <h3 className="text-lg font-bold">{project.title}</h3>
                                    </div>
                                    <div className="flex gap-2">
                                        <button onClick={() => handleDelete(project.id)} className="p-2 bg-red-500/20 text-red-400 rounded-lg hover:bg-red-500/30 transition-colors">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => {
                                                setCurrentProject(project);
                                                setIsEditing(true);
                                                window.scrollTo({ top: 0, behavior: 'smooth' });
                                            }}
                                            className="p-2 bg-blue-500/20 text-blue-400 rounded-lg hover:bg-blue-500/30 transition-colors"
                                        >
                                            <ExternalLink className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                                <div className="flex flex-wrap gap-1 mt-3">
                                    {project.tech?.slice(0, 3).map(t => (
                                        <span key={t} className="text-xs text-gray-500 bg-white/5 px-2 py-1 rounded">{t}</span>
                                    ))}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default ProjectsManager;

import React, { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { useToast } from '@/hooks/use-toast';
import { Trash2, Plus, RefreshCw, Copy } from 'lucide-react';

const PromoManager = () => {
    const [codes, setCodes] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    // Form State
    const [newCode, setNewCode] = useState("");
    const [type, setType] = useState<"flat" | "percent">("flat");
    const [value, setValue] = useState("");
    const [minOrder, setMinOrder] = useState("0");
    const [isSubmitting, setIsSubmitting] = useState(false);

    const fetchCodes = async () => {
        setLoading(true);
        const { data, error } = await supabase
            .from('promo_codes')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.error(error);
            toast({ title: "Error fetching codes", variant: "destructive" });
        } else {
            setCodes(data || []);
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchCodes();
    }, []);

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCode || !value) return;

        setIsSubmitting(true);
        const { error } = await supabase.from('promo_codes').insert({
            code: newCode.toUpperCase().trim(),
            discount_type: type,
            discount_value: Number(value),
            min_order_value: Number(minOrder),
            is_active: true
        });

        if (error) {
            toast({ title: "Error creating code", description: error.message, variant: "destructive" });
        } else {
            toast({ title: "Success!", description: `Code ${newCode} created.` });
            setNewCode("");
            setValue("");
            fetchCodes();
        }
        setIsSubmitting(false);
    };

    const handleDelete = async (id: string, code: string) => {
        if (!confirm(`Are you sure you want to delete ${code}?`)) return;

        const { error } = await supabase.from('promo_codes').delete().eq('id', id);
        if (error) {
            toast({ title: "Error deleting", variant: "destructive" });
        } else {
            toast({ title: "Deleted", description: `${code} removed.` });
            fetchCodes();
        }
    };

    const copyToClipboard = (text: string) => {
        navigator.clipboard.writeText(text);
        toast({ title: "Copied!", description: text });
    };

    return (
        <div className="p-8 max-w-7xl mx-auto text-white">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold bg-gradient-to-r from-purple-400 to-pink-400 bg-clip-text text-transparent">Promo Code Manager</h1>
                    <p className="text-gray-400">Create custom discount codes for your clients.</p>
                </div>
                <Button onClick={fetchCodes} variant="outline" className="border-white/10 text-white hover:bg-white/10">
                    <RefreshCw className="w-4 h-4 mr-2" /> Refresh
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* CREATE FORM */}
                <div className="bg-white/5 p-6 rounded-xl border border-white/10 h-fit">
                    <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <Plus className="w-5 h-5 text-purple-400" /> Create New Code
                    </h2>
                    <form onSubmit={handleCreate} className="space-y-4">
                        <div className="space-y-2">
                            <Label>Code Name</Label>
                            <Input
                                value={newCode}
                                onChange={(e) => setNewCode(e.target.value.toUpperCase())}
                                placeholder="e.g. VIPCLIENT2024"
                                className="bg-black/20 border-white/10 font-mono uppercase tracking-widest placeholder:normal-case placeholder:tracking-normal"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Type</Label>
                                <select
                                    className="w-full bg-black/20 border border-white/10 rounded-md p-2 text-sm"
                                    value={type}
                                    onChange={(e) => setType(e.target.value as "flat" | "percent")}
                                >
                                    <option value="flat">Flat Amount (₹)</option>
                                    <option value="percent">Percentage (%)</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <Label>Value</Label>
                                <Input
                                    type="number"
                                    value={value}
                                    onChange={(e) => setValue(e.target.value)}
                                    placeholder={type === 'flat' ? "5000" : "10"}
                                    className="bg-black/20 border-white/10"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <Label>Min Order Value (Optional)</Label>
                            <Input
                                type="number"
                                value={minOrder}
                                onChange={(e) => setMinOrder(e.target.value)}
                                placeholder="0"
                                className="bg-black/20 border-white/10"
                            />
                        </div>

                        <Button type="submit" className="w-full bg-purple-600 hover:bg-purple-700" disabled={isSubmitting}>
                            {isSubmitting ? "Creating..." : "Create Promo Code"}
                        </Button>
                    </form>
                </div>

                {/* LIST TABLE */}
                <div className="lg:col-span-2 bg-white/5 p-6 rounded-xl border border-white/10 overflow-hidden">
                    <h2 className="text-xl font-semibold mb-4">Active Coupons</h2>
                    {loading ? (
                        <p className="text-gray-400">Loading codes...</p>
                    ) : codes.length === 0 ? (
                        <p className="text-gray-400">No active codes found. Create one to get started.</p>
                    ) : (
                        <div className="overflow-x-auto">
                            <Table>
                                <TableHeader>
                                    <TableRow className="border-white/10 hover:bg-transparent">
                                        <TableHead className="text-gray-300">Code</TableHead>
                                        <TableHead className="text-gray-300">Discount</TableHead>
                                        <TableHead className="text-gray-300">Min Order</TableHead>
                                        <TableHead className="text-gray-300">Status</TableHead>
                                        <TableHead className="text-right text-gray-300">Actions</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {codes.map((code) => (
                                        <TableRow key={code.id} className="border-white/10 hover:bg-white/5">
                                            <TableCell className="font-mono font-bold text-lg text-purple-300 flex items-center gap-2">
                                                {code.code}
                                                <Copy
                                                    className="w-3 h-3 cursor-pointer text-gray-500 hover:text-white"
                                                    onClick={() => copyToClipboard(code.code)}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                {code.discount_type === 'flat' ? `₹${Number(code.discount_value).toLocaleString()}` : `${code.discount_value}% OFF`}
                                            </TableCell>
                                            <TableCell>
                                                ₹{Number(code.min_order_value).toLocaleString()}
                                            </TableCell>
                                            <TableCell>
                                                <Badge variant={code.is_active ? "default" : "destructive"}>
                                                    {code.is_active ? "Active" : "Inactive"}
                                                </Badge>
                                            </TableCell>
                                            <TableCell className="text-right">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-red-400 hover:text-red-300 hover:bg-red-900/20"
                                                    onClick={() => handleDelete(code.id, code.code)}
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default PromoManager;

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { Loader2, Save, RefreshCcw } from 'lucide-react';

interface Stat {
    id: number;
    label: string;
    value: string;
    icon_name: string;
}

const StatsManager = () => {
    const [stats, setStats] = useState<Stat[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const { toast } = useToast();

    const fetchStats = async () => {
        try {
            setLoading(true);
            const { data, error } = await supabase
                .from('stats')
                .select('*')
                .order('sort_order', { ascending: true });

            if (error) throw error;
            setStats(data || []);
        } catch (error: any) {
            toast({
                title: 'Error loading stats',
                description: error.message,
                variant: 'destructive',
            });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchStats();
    }, []);

    const handleUpdate = async (id: number, field: keyof Stat, cleanValue: string) => {
        const updatedStats = stats.map(s => s.id === id ? { ...s, [field]: cleanValue } : s);
        setStats(updatedStats);
    };

    const saveChanges = async () => {
        try {
            setSaving(true);

            // Upsert all modified stats
            const { error } = await supabase
                .from('stats')
                .upsert(stats.map(({ id, label, value }) => ({ id, label, value }))); // Only sending editable fields (and ID) is safest, but we can send all if needed. 
            // Wait, upsert needs all non-null columns if inserting, but here we are updating. 
            // Actually, best to just iterate and update or use upsert with all fields.
            // Let's use upsert with all relevant fields.

            const updates = stats.map(s => ({
                id: s.id,
                label: s.label,
                value: s.value,
                icon_name: s.icon_name, // Include this to avoid constraint errors if any, though not editing it yet.
            }));

            const { error: upsertError } = await supabase.from('stats').upsert(updates);
            if (upsertError) throw upsertError;

            toast({
                title: 'Success',
                description: 'Stats updated successfully',
            });
        } catch (error: any) {
            toast({
                title: 'Error saving changes',
                description: error.message,
                variant: 'destructive',
            });
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-3xl font-bold text-white">Manage Stats</h2>
                <button
                    onClick={saveChanges}
                    disabled={saving}
                    className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl font-bold text-white hover:opacity-90 transition-all disabled:opacity-50"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {stats.map((stat) => (
                    <div key={stat.id} className="bg-white/5 border border-white/10 rounded-2xl p-6 space-y-4">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center text-white font-bold">
                                {stat.icon_name.charAt(0)}
                            </div>
                            <span className="text-gray-400 text-sm font-mono">{stat.icon_name}</span>
                        </div>

                        <div>
                            <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wider">Value</label>
                            <input
                                type="text"
                                value={stat.value}
                                onChange={(e) => handleUpdate(stat.id, 'value', e.target.value)}
                                className="w-full bg-black/40 border border-white/10 rounded-lg px-3 py-2 text-white font-bold focus:outline-none focus:border-purple-500"
                            />
                        </div>

                        <div>
                            <label className="block text-xs text-gray-400 mb-1 uppercase tracking-wider">Label</label>
                            <input
                                type="text"
                                value={stat.label}
                                onChange={(e) => handleUpdate(stat.id, 'label', e.target.value)}
                                className="w-full bg-black/40 border border-white/10 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-purple-500"
                            />
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default StatsManager;

import React, { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Mail, Calendar, Trash2, Search, Users, Download } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { format } from 'date-fns';

interface Subscriber {
    id: number;
    email: string;
    subscribed_at: string;
}

const SubscribersManager = () => {
    const [subscribers, setSubscribers] = useState<Subscriber[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const { toast } = useToast();

    useEffect(() => {
        fetchSubscribers();
    }, []);

    const fetchSubscribers = async () => {
        try {
            const { data, error } = await supabase
                .from('subscribers')
                .select('*')
                .order('subscribed_at', { ascending: false });

            if (error) throw error;
            setSubscribers(data || []);
        } catch (error) {
            console.error('Error fetching subscribers:', error);
            toast({
                title: "Error",
                description: "Failed to load subscribers",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm('Are you sure you want to remove this subscriber?')) return;

        try {
            const { error } = await supabase
                .from('subscribers')
                .delete()
                .eq('id', id);

            if (error) throw error;

            setSubscribers(subscribers.filter(s => s.id !== id));
            toast({ title: "Success", description: "Subscriber removed" });
        } catch (error) {
            console.error('Error deleting subscriber:', error);
            toast({
                title: "Error",
                description: "Failed to remove subscriber",
                variant: "destructive"
            });
        }
    };

    const exportCSV = () => {
        const csvContent = "data:text/csv;charset=utf-8,"
            + "Email,Date Subscribed\n"
            + subscribers.map(s => `${s.email},${new Date(s.subscribed_at).toISOString()}`).join("\n");

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", "subscribers_list.csv");
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const filteredSubscribers = subscribers.filter(s =>
        s.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="p-6 text-white space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h2 className="text-3xl font-bold bg-gradient-to-r from-green-400 to-emerald-400 bg-clip-text text-transparent flex items-center gap-2">
                        <Users className="w-8 h-8 text-green-400" />
                        Subscribers
                    </h2>
                    <p className="text-gray-400 text-sm mt-1">Total: {subscribers.length} active subscribers</p>
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input
                            type="text"
                            placeholder="Search emails..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full bg-white/5 border border-white/10 rounded-full pl-10 pr-4 py-2 text-sm focus:border-green-500 outline-none transition-colors"
                        />
                    </div>
                    <button
                        onClick={exportCSV}
                        className="p-2 bg-white/5 hover:bg-white/10 rounded-full border border-white/10 transition-colors"
                        title="Export CSV"
                    >
                        <Download className="w-5 h-5 text-gray-300" />
                    </button>
                </div>
            </div>

            {loading ? (
                <div className="text-center py-20 text-gray-400">Loading list...</div>
            ) : filteredSubscribers.length === 0 ? (
                <div className="text-center py-20 bg-white/5 rounded-2xl border border-white/10">
                    <Mail className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold mb-2">No Subscribers Found</h3>
                    <p className="text-gray-400">Your list is empty.</p>
                </div>
            ) : (
                <div className="bg-white/5 border border-white/10 rounded-xl overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-black/20 text-gray-400 text-sm">
                            <tr>
                                <th className="p-4 font-medium">Email Address</th>
                                <th className="p-4 font-medium">Subscribed Date</th>
                                <th className="p-4 font-medium text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {filteredSubscribers.map((sub) => (
                                <tr key={sub.id} className="hover:bg-white/5 transition-colors group">
                                    <td className="p-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-full bg-green-500/10 flex items-center justify-center">
                                                <Mail className="w-4 h-4 text-green-400" />
                                            </div>
                                            <span className="font-medium text-gray-200">{sub.email}</span>
                                        </div>
                                    </td>
                                    <td className="p-4 text-gray-400">
                                        <div className="flex items-center gap-2">
                                            <Calendar className="w-3 h-3" />
                                            {format(new Date(sub.subscribed_at), 'PPP')}
                                        </div>
                                    </td>
                                    <td className="p-4 text-right">
                                        <button
                                            onClick={() => handleDelete(sub.id)}
                                            className="text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-2"
                                            title="Remove Subscriber"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default SubscribersManager;

import React, { useEffect, useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Plus, Trash2, Save, Star, Loader2, Undo } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface Testimonial {
    id: number;
    name: string;
    role: string;
    company: string;
    content: string;
    rating: number;
    image: string;
}

const TestimonialsManager = () => {
    const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    // New/Edit State
    const [editingId, setEditingId] = useState<number | 'new' | null>(null);
    const [formData, setFormData] = useState<Partial<Testimonial>>({});

    useEffect(() => {
        fetchTestimonials();
    }, []);

    const fetchTestimonials = async () => {
        try {
            setLoading(true);
            const { data, error } = await supabase
                .from('testimonials')
                .select('*')
                .order('created_at', { ascending: false });

            if (error) throw error;
            if (error) throw error;
            // Map DB fields back to form fields
            const mapped = (data || []).map((t) => {
                const [role, company] = (t.role || '').split(' @ ');
                return {
                    ...t,
                    role: role || t.role,
                    company: company || '',
                    image: t.image_url // Map image_url to image
                };
            });
            setTestimonials(mapped);
        } catch (error) {
            console.error('Error fetching testimonials:', error);
            toast({
                title: "Error",
                description: "Failed to load testimonials.",
                variant: "destructive"
            });
        } finally {
            setLoading(false);
        }
    };

    const handleEdit = (t: Testimonial) => {
        setEditingId(t.id);
        setFormData(t);
    };

    const handleCreate = () => {
        setEditingId('new');
        setFormData({
            name: '',
            role: '',
            company: '',
            content: '',
            rating: 5,
            image: 'https://images.unsplash.com/photo-1556157382-97eda2d62296?auto=format&fit=crop&w=150&q=80'
        });
    };

    const handleCancel = () => {
        setEditingId(null);
        setFormData({});
    };

    const handleSave = async () => {
        try {
            if (!formData.name || !formData.content) {
                toast({ title: "Validation Error", description: "Name and Content are required.", variant: "destructive" });
                return;
            }

            const payload = {
                name: formData.name,
                role: `${formData.role || ''} @ ${formData.company || ''}`, // Combine role and company
                content: formData.content,
                rating: formData.rating,
                image_url: formData.image // Map image to image_url
            };

            if (editingId === 'new') {
                const { error } = await supabase.from('testimonials').insert([payload]);
                if (error) throw error;
                toast({ title: "Success", description: "Testimonial created!" });
            } else {
                const { error } = await supabase
                    .from('testimonials')
                    .update(payload)
                    .eq('id', editingId);
                if (error) throw error;
                toast({ title: "Success", description: "Testimonial updated!" });
            }

            setEditingId(null);
            fetchTestimonials();

        } catch (error) {
            console.error('Error saving testimonial:', error);
            toast({ title: "Error", description: "Failed to save.", variant: "destructive" });
        }
    };

    const handleDelete = async (id: number) => {
        if (!window.confirm("Are you sure?")) return;
        try {
            const { error } = await supabase.from('testimonials').delete().eq('id', id);
            if (error) throw error;
            toast({ title: "Deleted", description: "Testimonial removed." });
            fetchTestimonials();
        } catch (error) {
            console.error('Error deleting:', error);
        }
    };

    if (loading) return <div className="text-white">Loading...</div>;

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-center">
                <div>
                    <h2 className="text-3xl font-bold text-white bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500">
                        Testimonials Manager
                    </h2>
                    <p className="text-gray-400">Manage client reviews and feedback.</p>
                </div>
                {!editingId && (
                    <button
                        onClick={handleCreate}
                        className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg transition-colors"
                    >
                        <Plus className="w-4 h-4" /> Add Testimonial
                    </button>
                )}
            </div>

            {(editingId) ? (
                <div className="bg-white/5 border border-white/10 rounded-xl p-6 space-y-4 max-w-2xl">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Client Name</label>
                            <input
                                className="w-full bg-black/50 border border-white/10 rounded p-2 text-white"
                                value={formData.name || ''}
                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Role / Position</label>
                            <input
                                className="w-full bg-black/50 border border-white/10 rounded p-2 text-white"
                                value={formData.role || ''}
                                onChange={e => setFormData({ ...formData, role: e.target.value })}
                            />
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Company</label>
                            <input
                                className="w-full bg-black/50 border border-white/10 rounded p-2 text-white"
                                value={formData.company || ''}
                                onChange={e => setFormData({ ...formData, company: e.target.value })}
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Rating (1-5)</label>
                            <select
                                className="w-full bg-black/50 border border-white/10 rounded p-2 text-white"
                                value={formData.rating || 5}
                                onChange={e => setFormData({ ...formData, rating: Number(e.target.value) })}
                            >
                                {[1, 2, 3, 4, 5].map(n => <option key={n} value={n}>{n} Stars</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm text-gray-400 mb-1">Avatar Image URL</label>
                        <input
                            className="w-full bg-black/50 border border-white/10 rounded p-2 text-white"
                            value={formData.image || ''}
                            onChange={e => setFormData({ ...formData, image: e.target.value })}
                        />
                    </div>

                    <div>
                        <label className="block text-sm text-gray-400 mb-1">Content / Review</label>
                        <textarea
                            className="w-full bg-black/50 border border-white/10 rounded p-2 text-white h-32"
                            value={formData.content || ''}
                            onChange={e => setFormData({ ...formData, content: e.target.value })}
                        />
                    </div>

                    <div className="flex gap-2 justify-end pt-4">
                        <button
                            onClick={handleCancel}
                            className="px-4 py-2 rounded-lg text-gray-300 hover:text-white hover:bg-white/5 flex items-center gap-2"
                        >
                            <Undo className="w-4 h-4" /> Cancel
                        </button>
                        <button
                            onClick={handleSave}
                            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg flex items-center gap-2"
                        >
                            <Save className="w-4 h-4" /> Save Testimonial
                        </button>
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {testimonials.map((t) => (
                        <div key={t.id} className="bg-white/5 border border-white/10 rounded-xl p-4 flex gap-4 group hover:border-purple-500/30 transition-all">
                            <img src={t.image} alt={t.name} className="w-16 h-16 rounded-full object-cover" />
                            <div className="flex-1">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h3 className="font-bold text-white">{t.name}</h3>
                                        <p className="text-sm text-purple-400">{t.role} @ {t.company}</p>
                                    </div>
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => handleEdit(t)} className="p-1.5 hover:bg-blue-500/20 rounded text-blue-400"><Save className="w-4 h-4" /></button>
                                        <button onClick={() => handleDelete(t.id)} className="p-1.5 hover:bg-red-500/20 rounded text-red-400"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 my-2">
                                    {[...Array(5)].map((_, i) => (
                                        <Star key={i} className={`w-3 h-3 ${i < t.rating ? 'text-yellow-400 fill-yellow-400' : 'text-gray-600'}`} />
                                    ))}
                                </div>
                                <p className="text-sm text-gray-300 line-clamp-2">"{t.content}"</p>
                            </div>
                        </div>
                    ))}
                    {testimonials.length === 0 && (
                        <div className="col-span-2 text-center py-20 text-gray-500 italic">No testimonials found. Create one!</div>
                    )}
                </div>
            )}
        </div>
    );
};

export default TestimonialsManager;

import React, { useEffect } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { CheckCircle, Download, ArrowRight, Home, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { jsPDF } from 'jspdf';
import Header from '@/components/Header';
import Footer from '@/components/Footer';

const PaymentSuccess = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const state = location.state as {
        paymentId?: string;
        orderId?: string;
        amount?: number;
        planName?: string;
        companyName?: string;
        date?: string;
    } || {};

    useEffect(() => {
        if (!state.paymentId) {
            // If accessed directly without state, redirect to home after 5s or show generic message
            // navigate('/'); 
        }
    }, [state, navigate]);

    const generateReceipt = () => {
        const doc = new jsPDF();
        doc.setFontSize(22);
        doc.setTextColor(147, 51, 234); // Purple
        doc.text("YourWebPartner", 20, 20);

        doc.setFontSize(16);
        doc.setTextColor(0, 0, 0);
        doc.text("Payment Receipt", 20, 35);

        doc.setFontSize(12);
        doc.text(`Date: ${state.date || new Date().toLocaleDateString()}`, 20, 45);
        doc.text(`Order ID: ${state.orderId || 'N/A'}`, 20, 52);
        doc.text(`Payment ID: ${state.paymentId || 'N/A'}`, 20, 59);

        doc.line(20, 65, 190, 65);

        doc.text("Item", 20, 75);
        doc.text("Cost", 160, 75);

        doc.line(20, 80, 190, 80);

        doc.text(`${state.planName || 'Service Plan'}`, 20, 90);
        doc.text(`Rs. ${(state.amount || 0).toLocaleString()}`, 160, 90);

        doc.line(20, 100, 190, 100);

        doc.setFontSize(14);
        doc.text(`Total Paid: Rs. ${(state.amount || 0).toLocaleString()}`, 120, 115);

        doc.save("receipt.pdf");
    };

    return (
        <div className="min-h-screen bg-black text-white font-sans selection:bg-green-500/30">
            <Header />

            <div className="pt-32 pb-20 px-4 min-h-[80vh] flex items-center justify-center relative overflow-hidden">
                {/* Background Effects */}
                <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-green-600/10 rounded-full blur-[100px] pointer-events-none animate-pulse"></div>

                <div className="max-w-2xl w-full bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-8 md:p-12 relative z-10 text-center animate-fade-in">
                    <div className="w-24 h-24 bg-green-500/20 text-green-400 rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce">
                        <CheckCircle className="w-12 h-12" />
                    </div>

                    <h1 className="text-4xl md:text-5xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-green-400 to-emerald-600">
                        Payment Successful!
                    </h1>

                    <p className="text-xl text-gray-300 mb-8 leading-relaxed">
                        Thank you for partnering with us. Your transaction for <span className="text-white font-bold">{state.planName}</span> has been verified.
                    </p>

                    <div className="bg-black/30 rounded-2xl p-6 mb-8 text-left space-y-3 border border-white/5">
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-400">Payment ID</span>
                            <span className="font-mono text-white">{state.paymentId}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-400">Amount Paid</span>
                            <span className="font-bold text-green-400">₹{(state.amount || 0).toLocaleString()}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-400">Status</span>
                            <span className="flex items-center gap-1 text-green-400"><ShieldCheck className="w-3 h-3" /> Verified</span>
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-4 justify-center">
                        <Button onClick={generateReceipt} variant="outline" className="h-12 border-white/20 hover:bg-white/10 gap-2">
                            <Download className="w-4 h-4" /> Download Receipt
                        </Button>
                        <Link to="/admin">
                            <Button className="h-12 bg-white text-black hover:bg-gray-200 gap-2 w-full sm:w-auto font-bold px-8">
                                Go to Dashboard <ArrowRight className="w-4 h-4" />
                            </Button>
                        </Link>
                    </div>

                    <div className="mt-8 pt-8 border-t border-white/5">
                        <Link to="/" className="text-gray-500 hover:text-white flex items-center justify-center gap-2 text-sm transition-colors">
                            <Home className="w-4 h-4" /> Back to Home
                        </Link>
                    </div>
                </div>
            </div>

            <Footer />
        </div>
    );
};

export default PaymentSuccess;
